(function(){
  const config=window.SITE_CONFIG||{};
  const booking=config.NEXT_PUBLIC_BOOKING_URL||"/contact/";
  const current=location.pathname;
  const header=document.querySelector("[data-site-header]");
  if(header) header.innerHTML=`<header class="site-header"><a class="brand" href="/" aria-label="Abhinav Shrestha, home"><span class="brand-mark">AS</span><span>Abhinav Shrestha</span></a><nav class="desktop-nav" aria-label="Primary navigation"><a ${current==='/'?'aria-current="page"':''} href="/">Home</a><a ${current.startsWith('/about')?'aria-current="page"':''} href="/about/">About</a><a ${current.startsWith('/services')?'aria-current="page"':''} href="/services/">Services</a><a ${current.startsWith('/blog')?'aria-current="page"':''} href="/blog/">Insights</a><a ${current.startsWith('/contact')?'aria-current="page"':''} href="/contact/">Contact</a></nav><a class="button button-small booking-link" href="${booking}">Book a Free Call</a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="mobile-menu" aria-label="Open menu"><span></span><span></span></button></header><div class="mobile-menu" id="mobile-menu" hidden><a href="/">Home</a><a href="/about/">About Me</a><a href="/services/">Services</a><a href="/blog/">Insights</a><a href="/contact/">Contact</a><a class="button booking-link" href="${booking}">Book a Free Consultation Call</a></div>`;
  document.querySelectorAll('.booking-link').forEach(a=>{a.href=booking;if(booking!=="/contact/"){a.target="_blank";a.rel="noopener"}});
  const toggle=document.querySelector('.menu-toggle'), menu=document.querySelector('.mobile-menu');
  toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));toggle.setAttribute('aria-label',open?'Open menu':'Close menu');menu.hidden=open;document.body.classList.toggle('menu-open',!open)});
  const footer=document.querySelector("[data-site-footer]");
  if(footer) footer.innerHTML=`<footer class="footer"><div class="shell footer-grid"><div><a class="brand brand-light" href="/"><span class="brand-mark brand-mark-light">AS</span><span>Abhinav Shrestha</span></a><p>Practical AI and digital marketing strategy for small and medium-sized businesses.</p></div><div><h3>Explore</h3><a href="/about/">About</a><a href="/services/">Services</a><a href="/blog/">Insights</a><a href="/contact/">Contact</a></div><div><h3>Services</h3><a href="/services/#meta-ads">Meta Ads</a><a href="/services/#digital-marketing">Digital Marketing</a><a href="/services/#email-marketing">Email Marketing</a></div><div><h3>Start a conversation</h3><p>Bring your questions. Leave with a clearer view of your next move.</p><a class="button button-light booking-link" href="${booking}">Book a Free Consultation Call</a></div></div><div class="shell footer-bottom"><span>© ${new Date().getFullYear()} Abhinav Shrestha</span><span><a href="/privacy/">Privacy</a><a href="/terms/">Terms</a></span></div></footer>`;
  document.querySelectorAll('[data-accordion]').forEach(item=>{const b=item.querySelector('button');b?.addEventListener('click',()=>{const open=item.hasAttribute('open');document.querySelectorAll('[data-accordion][open]').forEach(x=>x.removeAttribute('open'));if(!open)item.setAttribute('open','')})});
  const form=document.querySelector('#contact-form');
  if(form){const status=document.querySelector('#form-status'),submit=form.querySelector('button[type=submit]');form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;submit.disabled=true;submit.textContent='Preparing your request…';status.className='form-status is-loading';status.textContent='Checking your consultation details…';if(!config.FORM_ENDPOINT){setTimeout(()=>{status.className='form-status is-notice';status.innerHTML='<strong>Your details are ready.</strong> The form service has not been connected yet, so nothing was sent. Please return once a contact endpoint is configured.';submit.disabled=false;submit.textContent='Request My Free Consultation'},650);return}try{const body=new FormData(form);const res=await fetch(config.FORM_ENDPOINT,{method:'POST',body});if(!res.ok)throw new Error();form.reset();status.className='form-status is-success';status.innerHTML='<strong>Thank you.</strong> Your consultation request has been sent. I’ll be in touch soon.'}catch{status.className='form-status is-error';status.innerHTML='<strong>That didn’t send.</strong> Please try again in a moment.'}finally{submit.disabled=false;submit.textContent='Request My Free Consultation'}})}
  const observer=new IntersectionObserver(items=>items.forEach(i=>{if(i.isIntersecting){i.target.classList.add('in');observer.unobserve(i.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
})();
